effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   /////////////////////////



    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 umefx;
        // if (adaptive) { umefx = acScreenNorm; }
        // else { 
        umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        umefx.y*=acLayerSize.y/acLayerSize.x;
        // }

        umefx /= scale;
        umefx *= rot2m(angle*0.0174533);
        umefx += position*vec2(-1.,1.)/500.;

        vec2 scaleVec;
        vec2 fragSize = vec2(1.)/inputImg.size;

        if(acScreenSize.x > acScreenSize.y) { scaleVec = vec2(scale*(stretch.x+1.0),scale*stretch.y); }
        else if(acScreenSize.x < acScreenSize.y) { scaleVec = vec2(scale*stretch.x,scale*(stretch.y+1.0)); }
        else { scaleVec = vec2(scale*stretch.x,scale*stretch.y); }
        umefx /= scaleVec;

        /////////////////////////

      vec4 result;
      vec2 uv = umefx;

      float g = 0., l=0.;
      const float N = 16.;
      for (float i=0.; i<N; i++) {
        g+=sqrt(1./N)*(-.5+texture2DCv(noise.texture, uv*vec2(.06,4.18)+i*vec2((7.+1./N)/256.)).x);
        l+=sqrt(1./N)*(-.5+texture2DCv(noise.texture, vec2(0.,.5)+uv*vec2(.04,0.004)+i*vec2((10.+1./N)/256.)).x);
      }
      l = exp(4.*l-1.5);
      g = exp(1.2*g-1.5);
      float v = .1*g+.2*l+2.*g*l;

      vec3 col = vec3(v);

      result = vec4(pow(col,vec3(1./2.2)),1.0);

        vec4 factorr;
        if(texC==0) { factorr = result * texColor.a; }
        else if(texC==1) { umefx *= 70.0; factorr = texture2DCv(dots.texture,umefx); }
    	else if(texC==2) { umefx *= 3.5; factorr = texture2DCv(t11.texture,umefx); }

            const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            vec4 gradmap;
            float luminance = dot(factorr.rgb, luminanceWeighting);
            gradmap = mix(color1,color2,luminance)*factorr.a;

    	vec4 factor = grad? mix(texColorX,gradmap,1.0) : mix(texColorX,factorr,1.0);
    	// vec4 factor = mix(texColorX,result,alpha);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
    }
